import{_ as s,C as i,o,c as r,j as t,a,E as d,ao as h}from"./chunks/framework.ucUddl5u.js";const k=JSON.parse('{"title":"The Concept Layer","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concept-layer.md","filePath":"guide/concept-layer.md","lastUpdated":null}'),l={name:"guide/concept-layer.md"};function c(p,e,g,y,u,f){const n=i("DemoShot");return o(),r("div",null,[e[0]||(e[0]=t("h1",{id:"The-Concept-Layer",tabindex:"-1"},[a("The Concept Layer "),t("a",{class:"header-anchor",href:"#The-Concept-Layer","aria-label":'Permalink to "The Concept Layer {#The-Concept-Layer}"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("The concept layer is what makes Ship of Tools a "),t("em",null,"concept explorer"),a(" rather than a file browser. It is prose — intent, contracts, meaning, math — attached to the units of a Julia project and kept honest against the code those units describe. The LLM is the primary author and maintainer of this layer; the user can edit it too.")],-1)),d(n,{name:"concept-stale",caption:"The annotation line marks the file's annotation STALE: the file changed after the annotation was written."}),e[2]||(e[2]=h(`<p>It is built from two layers with very different update mechanics. Keep them separate in your head:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Layer</th><th style="text-align:right;">Source</th><th style="text-align:right;">Currency</th><th style="text-align:right;">LLM involved?</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Structural</strong></td><td style="text-align:right;">parsed mechanically from code via <code>JuliaSyntax.jl</code> (plus live introspection where the project is loaded)</td><td style="text-align:right;">always current</td><td style="text-align:right;">no</td></tr><tr><td style="text-align:right;"><strong>Annotation</strong></td><td style="text-align:right;">LLM- or user-authored prose attached to nodes in the structural layer</td><td style="text-align:right;">can drift</td><td style="text-align:right;">yes</td></tr></tbody></table><p>The structural layer is derived, never stored as a fact you can get wrong — it is recomputed from the source. The annotation layer is the part that can fall out of sync, so the whole design below is about <em>detecting and surfacing that drift</em> rather than trying to prevent it.</p><h2 id="The-.concept/-sidecar" tabindex="-1">The <code>.concept/</code> sidecar <a class="header-anchor" href="#The-.concept/-sidecar" aria-label="Permalink to &quot;The \`.concept/\` sidecar {#The-.concept/-sidecar}&quot;">​</a></h2><p>Annotations live in a sidecar <code>.concept/</code> directory at the project root, mirroring the conceptual structure of the project:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.concept/</span></span>
<span class="line"><span>  project/intent.md</span></span>
<span class="line"><span>  modules/MyModule.md</span></span>
<span class="line"><span>  types/MyModule/MyType.md</span></span>
<span class="line"><span>  functions/MyModule/myfunction.md</span></span>
<span class="line"><span>  math/geometry/rotation.md</span></span></code></pre></div><p>The directory is plain files on disk. That is deliberate: it survives a restart, diffs cleanly in git, and is readable without Ship of Tools running. Each path corresponds to a node you can navigate to in a mode — a module in Modules mode, a type in Types mode, a derivation in Math mode — so the annotation for a node is always at a predictable location.</p><h2 id="Frontmatter" tabindex="-1">Frontmatter <a class="header-anchor" href="#Frontmatter" aria-label="Permalink to &quot;Frontmatter {#Frontmatter}&quot;">​</a></h2><p>Each annotation file carries YAML frontmatter that ties the prose to the entity it describes and records when it was last reconciled:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">MyModule.MyType</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">target_kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">type</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">synced_against</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;ast_hash&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">synced_at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2026-01-15T14:30Z</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">authored_by</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">orchestrator | user</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">references</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">MyModule.method1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">math/geometry/rotation</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:right;">Field</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>target</code></td><td style="text-align:right;">the entity this annotation describes</td></tr><tr><td style="text-align:right;"><code>target_kind</code></td><td style="text-align:right;">what kind of entity (<code>type</code>, <code>function</code>, <code>module</code>, …)</td></tr><tr><td style="text-align:right;"><code>synced_against</code></td><td style="text-align:right;">the AST hash of <code>target</code> at the last reconciliation</td></tr><tr><td style="text-align:right;"><code>synced_at</code></td><td style="text-align:right;">timestamp of that reconciliation</td></tr><tr><td style="text-align:right;"><code>authored_by</code></td><td style="text-align:right;"><code>orchestrator</code> or <code>user</code> — provenance feeds <a href="./color-coding">Color Coding</a></td></tr><tr><td style="text-align:right;"><code>references</code></td><td style="text-align:right;">links to other entities or annotations (verification is planned — see below)</td></tr></tbody></table><p>The load-bearing field is <code>synced_against</code>. It is the AST hash of the target as of the last time the annotation was confirmed accurate. Staleness is just a comparison: recompute the target&#39;s hash now, and if it differs from <code>synced_against</code>, the prose was written against an older version of the code. Today <code>synced_against</code> is the only field the backend parses; the rest of the frontmatter is preserved verbatim across edits and shown above the editor, but is not otherwise acted on.</p><h2 id="The-AST-hash" tabindex="-1">The AST hash <a class="header-anchor" href="#The-AST-hash" aria-label="Permalink to &quot;The AST hash {#The-AST-hash}&quot;">​</a></h2><p>The hash is computed from the parsed AST of the targeted entity, not its raw text, so it ignores changes that don&#39;t matter and catches changes that do:</p><ul><li><p>Reformatting and whitespace <strong>outside</strong> string literals → same hash. Running a formatter does not mark anything stale.</p></li><li><p>Whitespace <strong>inside</strong> docstrings or string literals → different hash. A meaningful docstring edit is a meaningful change.</p></li><li><p>Variable renames → different hash.</p></li></ul><p>The algorithm walks the <code>JuliaSyntax.SyntaxNode</code> tree depth-first — <code>SyntaxNode</code> already excludes trivia (whitespace and comments) — emitting each node&#39;s <code>kind</code> and, for leaf nodes, the node&#39;s source text. That byte stream is hashed with SHA-256 and rendered as the full 64-character hex digest (no truncation, no version prefix).</p><h2 id="Update-lifecycle" tabindex="-1">Update lifecycle <a class="header-anchor" href="#Update-lifecycle" aria-label="Permalink to &quot;Update lifecycle {#Update-lifecycle}&quot;">​</a></h2><p>Drift detection is reactive — Ship of Tools surfaces it, you fix it when you choose to:</p><ol><li><p><strong>You save a file.</strong> (Either you edited it, or the orchestrator did.)</p></li><li><p><strong>The kernel re-parses the affected files</strong> and recomputes AST hashes for the entities in them.</p></li><li><p><strong>Annotations whose target&#39;s hash changed are marked stale.</strong> The comparison is <code>current_hash != synced_against</code>.</p></li><li><p><strong>Stale annotations render with a yellowed / wilting badge</strong> — and they render that way in <em>every</em> mode, because staleness is a property of the entity&#39;s provenance, not of any one view. See <a href="./color-coding">Color Coding</a>.</p></li></ol><p>There is no background sweep in phase 1. Nothing recomputes annotations on a timer or refreshes them behind your back. Visible drift is the feature: a yellowed badge tells you the prose may no longer match the code.</p><h2 id="Reactive-refresh" tabindex="-1">Reactive refresh <a class="header-anchor" href="#Reactive-refresh" aria-label="Permalink to &quot;Reactive refresh {#Reactive-refresh}&quot;">​</a></h2><p>The intended model is reactive: navigate to the stale annotation and trigger a refresh with a single keypress that re-stamps <code>synced_against</code> (and <code>synced_at</code>) to the target&#39;s current hash, marking the prose as reconciled against the present code. You stay in control of <em>when</em> — a refresh asserts the annotation is still accurate, so it is a deliberate act, not an automatic one.</p><p>That one-key re-stamp is not yet built. Today you reconcile a stale annotation by editing it in place (<code>e</code>), updating its <code>synced_against</code> in the frontmatter, and saving (<code>Ctrl+S</code>); <code>Esc</code> discards. A background staleness sweep is also explicitly deferred; refresh is on-demand only.</p><h2 id="Reference-verification-planned" tabindex="-1">Reference verification (planned) <a class="header-anchor" href="#Reference-verification-planned" aria-label="Permalink to &quot;Reference verification (planned) {#Reference-verification-planned}&quot;">​</a></h2><p>The <code>references</code> list links an annotation to other entities (<code>MyModule.method1</code>) or to other annotations (<code>math/geometry/rotation</code>). A background pass that verifies these links after every re-index is planned: when a referenced entity no longer exists — a method was deleted, a derivation renamed — the link would be broken, and the annotation marked stale on that basis too, keeping the concept layer internally consistent, not just consistent with code. Today the <code>references</code> field is preserved on disk but not verified.</p><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><a href="./color-coding">Color Coding</a> — how staleness and authorship render across modes.</li></ul>`,27))])}const b=s(l,[["render",c]]);export{k as __pageData,b as default};
